def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Treat small non-background components as stray marks.
    seen = set()
    noise = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            for y, x in q:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(q) == 1:
                noise.add(q[0])

    out = [row[:] for row in grid]
    for r, c in noise:
        candidates = set()
        for y0 in (r - 1, r):
            for x0 in (c - 1, c):
                cells = [(y, x) for y in (y0, y0 + 1)
                                  for x in (x0, x0 + 1)
                         if 0 <= y < h and 0 <= x < w and (y, x) != (r, c)]
                if len(cells) == 3:
                    freq = Counter(grid[y][x] for y, x in cells)
                    color, count = freq.most_common(1)[0]
                    if count == 3:
                        candidates.add(color)

        non_bg = candidates - {bg}
        if non_bg:
            # Prefer filling a solid object rather than extending the field.
            out[r][c] = max(non_bg, key=lambda color: sum(
                grid[y][x] == color
                for y in range(max(0, r - 2), min(h, r + 3))
                for x in range(max(0, c - 2), min(w, c + 3))
            ))
        elif bg in candidates:
            out[r][c] = bg
        else:
            out[r][c] = bg
    return out
